package vn.vinhkhang.warehouse;
import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
@RestController @RequestMapping("/api/purge")
public class PermanentDelete {
 final Api core;final JdbcTemplate db;final TransactionTemplate tx;final ObjectMapper json;
 public PermanentDelete(Api core,JdbcTemplate db,PlatformTransactionManager tm,ObjectMapper json){this.core=core;this.db=db;tx=new TransactionTemplate(tm);this.json=json;}
 static final Map<String,String> TABLES=Map.of("parts","parts","suppliers","suppliers","models","vehicle_models","bom","bom_versions","documents","stock_documents","production","production_orders","receipts","vehicle_receipts","shipments","vehicle_shipments","audit","audit_log");
 @ExceptionHandler(Api.Problem.class) public org.springframework.http.ResponseEntity<?> problem(Api.Problem e){return org.springframework.http.ResponseEntity.status(e.status).body(Map.of("message",e.getMessage()));}
 @ExceptionHandler(org.springframework.dao.DataIntegrityViolationException.class) public org.springframework.http.ResponseEntity<?> conflict(Exception e){return org.springframework.http.ResponseEntity.status(409).body(Map.of("message","Bản ghi còn được sử dụng. Chưa xóa hẳn dòng nào; các dữ liệu khác giữ nguyên."));}
 List<Long> ids(Map<String,Object> body){if(!(body.get("ids") instanceof List<?> raw)||raw.isEmpty()||raw.size()>1000)throw new Api.Problem(400,"Chọn từ 1 đến 1000 dòng");var out=new TreeSet<Long>();for(Object v:raw){long id;try{id=Long.parseLong(v.toString());}catch(Exception e){throw new Api.Problem(400,"ID không hợp lệ");}if(id<=0||!out.add(id))throw new Api.Problem(400,"Dòng bị trùng hoặc không hợp lệ");}return List.copyOf(out);}
 void blocked(String sql,long id,String message){if(db.queryForObject(sql,Integer.class,id)>0)throw new Api.Problem(409,message+". Chưa xóa hẳn dòng nào.");}
 Map<String,Object> preview(String token,String entity,Map<String,Object> body,boolean lock){var actor=core.admin(token);if(!TABLES.containsKey(entity))throw new Api.Problem(400,"Mục này chưa hỗ trợ xóa hẳn");if(AccountKinds.get(db,actor.id()).equals("STORE")&&Set.of("bom","production").contains(entity))throw new Api.Problem(403,"Chức năng dành cho nhà máy");var ids=ids(body);var records=new ArrayList<Map<String,Object>>();for(long id:ids){var found=db.queryForList("SELECT * FROM "+TABLES.get(entity)+" WHERE id=?"+(lock?" FOR UPDATE":""),id);if(found.isEmpty())throw new Api.Problem(409,"Dòng #"+id+" không còn tồn tại");records.add(found.getFirst());switch(entity){
 case "parts"->{blocked("SELECT COUNT(*) FROM bom_lines WHERE part_id=?",id,"Linh kiện còn trong BOM");blocked("SELECT COUNT(*) FROM stock_document_lines WHERE part_id=?",id,"Linh kiện còn trong phiếu kho");blocked("SELECT COUNT(*) FROM production_materials WHERE part_id=?",id,"Linh kiện còn trong lệnh sản xuất");blocked("SELECT COUNT(*) FROM parts WHERE color_parent_id=?",id,"Linh kiện còn biến thể màu");blocked("SELECT COUNT(*) FROM stock_movements WHERE part_id=?",id,"Linh kiện còn ảnh hưởng kho đã ghi");blocked("SELECT COUNT(*) FROM retained_stock_effects WHERE part_id=?",id,"Linh kiện còn số liệu kho đã chốt");blocked("SELECT COUNT(*) FROM stock_balances WHERE part_id=? AND quantity<>0",id,"Linh kiện còn tồn kho");}
 case "suppliers"->blocked("SELECT COUNT(*) FROM stock_documents WHERE supplier_id=?",id,"Nhà cung cấp còn trong phiếu kho");
 case "models"->{blocked("SELECT COUNT(*) FROM bom_versions WHERE model_id=?",id,"Mẫu xe còn BOM");blocked("SELECT COUNT(*) FROM vehicles WHERE model_id=?",id,"Mẫu xe còn xe đã ghi nhận");blocked("SELECT COUNT(*) FROM part_color_models WHERE model_id=?",id,"Mẫu xe còn phân loại màu linh kiện");blocked("SELECT COUNT(*) FROM parts WHERE color_model_id=?",id,"Mẫu xe còn linh kiện theo màu");}
 case "bom"->{blocked("SELECT COUNT(*) FROM production_orders WHERE bom_id=?",id,"BOM còn lệnh sản xuất");blocked("SELECT COUNT(*) FROM production_order_lines WHERE bom_id=?",id,"BOM còn dòng lệnh sản xuất");}
 case "documents"->{blocked("SELECT COUNT(*) FROM vehicle_shipments WHERE charger_document_id=?",id,"Phiếu sạc còn gắn với xuất xe; anh chọn xóa hẳn phiếu xuất xe gốc");var returns=db.queryForList("SELECT id FROM stock_documents WHERE return_source_id=?",Long.class,id);if(returns.stream().anyMatch(v->!ids.contains(v)))throw new Api.Problem(409,"Phiếu nhập còn phiếu trả NCC; chọn cùng các phiếu trả hoặc giữ phiếu nhập");}
 default->{} }
 }
 String fingerprint;try{fingerprint=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(records)));}catch(Exception e){throw new Api.Problem(500,"Không kiểm tra được dữ liệu");}
 return Map.of("ids",ids,"entity",entity,"fingerprint",fingerprint,"names",records.stream().map(r->Objects.toString(r.getOrDefault("CODE",r.getOrDefault("NAME",r.get("ID"))))).toList(),"note","Xóa hẳn thông tin đã chọn, không hoàn tồn và không đổi số lượng kho, trạng thái xe, giá vốn, doanh số hoặc thu/chi còn lại. Các số liệu đã ghi được giữ độc lập, không còn liên kết tới phiếu đã xóa. Không khôi phục từng dòng đã xóa hẳn; chỉ có bản sao lưu trước xóa.");
 }
 @PostMapping("/{entity}/preview") public Object preview(@RequestHeader("Authorization") String token,@PathVariable String entity,@RequestBody Map<String,Object> body){return preview(token,entity,body,false);}
 @PostMapping("/{entity}") public synchronized Object purge(@RequestHeader("Authorization") String token,@PathVariable String entity,@RequestBody Map<String,Object> body){var actor=core.admin(token);if(!"XOA HAN".equals(body.get("confirmation")))throw new Api.Problem(400,"Nhập XOA HAN để xác nhận");core.str(body,"reason");preview(token,entity,body,false);var backup=core.backup(token);
 tx.executeWithoutResult(status->{var plan=preview(token,entity,body,true);if(!Objects.equals(plan.get("fingerprint"),body.get("fingerprint")))throw new Api.Problem(409,"Dữ liệu đã thay đổi. Anh xem lại trước khi xóa hẳn");var ids=ids(body);for(long id:ids){switch(entity){
 case "documents"->{detachRevenue("PART",id);archive("document_id",id);db.update("DELETE FROM stock_document_lines WHERE document_id=?",id);db.update("UPDATE stock_documents SET return_source_id=NULL WHERE return_source_id=?",id);}
 case "shipments"->{detachRevenue("VEHICLE",id);Long doc=ShipmentChargers.document(db,id);db.update("DELETE FROM vehicle_shipment_lines WHERE shipment_id=?",id);db.update("UPDATE vehicle_shipments SET charger_document_id=NULL WHERE id=?",id);if(doc!=null){archive("document_id",doc);db.update("DELETE FROM stock_document_lines WHERE document_id=?",doc);clean("documents",doc);db.update("DELETE FROM stock_documents WHERE id=?",doc);}}
 case "production"->{archive("production_id",id);db.update("UPDATE vehicles SET order_id=NULL,production_line_id=NULL WHERE order_id=?",id);db.update("UPDATE vehicle_receipts SET production_order_id=NULL WHERE production_order_id=?",id);db.update("DELETE FROM production_line_materials WHERE line_id IN(SELECT id FROM production_order_lines WHERE order_id=?)",id);db.update("DELETE FROM production_materials WHERE order_id=?",id);db.update("DELETE FROM production_order_lines WHERE order_id=?",id);}
 case "receipts"->db.update("UPDATE vehicles SET receipt_id=NULL WHERE receipt_id=?",id);
 case "parts"->{db.update("DELETE FROM part_color_models WHERE part_id=?",id);db.update("DELETE FROM stock_balances WHERE part_id=?",id);}
 case "bom"->db.update("DELETE FROM bom_lines WHERE bom_id=?",id);
 default->{} }
 clean(entity,id);db.update("DELETE FROM "+TABLES.get(entity)+" WHERE id=?",id);
 }core.audit(actor,"PURGE","database",0);});return Map.of("purged",true,"count",ids(body).size(),"backup",backup.get("file"));
 }
 void clean(String entity,long id){db.update("DELETE FROM deleted_records WHERE entity=? AND entity_id=?",entity,id);db.update("DELETE FROM audit_log WHERE entity=? AND entity_id=?",entity,id);}
 void archive(String column,long id){db.update("INSERT INTO retained_stock_effects(group_key,part_id,location_id,quantity,unit_cost,created_at) SELECT ?,part_id,location_id,quantity,unit_cost,created_at FROM stock_movements WHERE "+column+"=?",UUID.randomUUID().toString(),id);db.update("DELETE FROM stock_movements WHERE "+column+"=?",id);}
 void detachRevenue(String type,long id){String code=db.queryForObject("SELECT code FROM "+(type.equals("PART")?"stock_documents":"vehicle_shipments")+" WHERE id=?",String.class,id);db.update("UPDATE revenue_sales SET source_detached=TRUE,source_code=?,source_id=-id WHERE source_type=? AND source_id=?",code,type,id);}
}
